import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class GoodFileAccess {
    public static void main(String[] args) {
        String userInput = "safe_file.txt"; // Simulated user input

        // Define the base directory
        String baseDir = "/var/data/";

        // Construct the full path using the base directory and the filename
        Path basePath = Paths.get(baseDir).toAbsolutePath().normalize();
        Path filePath = Paths.get(baseDir, userInput).toAbsolutePath().normalize();

        // Ensure the resolved path starts with the base directory to prevent traversal
        if (!filePath.startsWith(basePath)) {
            throw new SecurityException("Invalid path detected");
        }

        try {
            byte[] data = Files.readAllBytes(filePath);
            System.out.println("Read file: " + data.length);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
